parameters.jsCode:
// AI лише витягує факти. Скор і пріоритет рахує код — прозоро і перевірювано.
const o = $json.output || {};
const src = $('Нова заявка (Webhook)').item.json.body;
const pick = (v, allowed, def) => allowed.includes(v) ? v : def;
const partner = pick(o.partner_type, ['designer','studio','developer','hotel','contractor','private'], 'unknown');
const objType = pick(o.object_type, ['apartment','house','commercial','hotel','office'], 'unknown');
const stage  = pick(o.renovation_stage, ['project','rough','finish','done'], 'unknown');
const systems = (Array.isArray(o.systems) ? o.systems : []).filter(s => ['lighting','climate','security','multiroom','curtains'].includes(s));
const area = Number.isInteger(o.area_m2) && o.area_m2 > 0 && o.area_m2 < 100000 ? o.area_m2 : null;
const budget = Number.isInteger(o.budget_usd) && o.budget_usd > 0 ? o.budget_usd : null;

// --- скоринг 0–100 ---
let score = 0;
score += {project:30, rough:30, finish:10, done:5, unknown:0}[stage];
score += {developer:25, hotel:25, studio:20, designer:20, contractor:15, private:10, unknown:0}[partner];
if (area) score += area >= 150 ? 15 : area >= 80 ? 10 : 5;
if (o.units && o.units > 1) score += 15;
if (budget) score += 10;
if (o.timeline) score += 10;
if (systems.length >= 3) score += 10; else if (systems.length) score += 5;
score = Math.min(100, score);
const temp = score >= 70 ? 'hot' : score >= 40 ? 'warm' : 'cold';

// --- ID з Odoo (your-company) ---
const TAG = {designer:1, studio:2, developer:3, hotel:4, contractor:5, private:6, hot:7, warm:8, cold:9, instagram:10, tiktok:11, callcenter:12, target:13};
const TEAM = partner === 'private' || partner === 'unknown' ? 1 : 4;   // 1 = Прямі клієнти, 4 = Партнери
const tags = [TAG[partner], TAG[temp], TAG[src.channel]].filter(Boolean);

const L = {
  partner: {designer:'Дизайнер', studio:'Студія', developer:'Забудовник', hotel:'Готель', contractor:'Електрик/прораб', private:'Приватний', unknown:'Невідомо'},
  obj: {apartment:'квартира', house:'будинок', commercial:'комерція', hotel:'готель', office:'офіс', unknown:'об\'єкт'},
  stage: {project:'проєкт', rough:'чорновий ремонт', finish:'чистовий ремонт', done:'ремонт завершено', unknown:'невідомо'},
  temp: {hot:'🔥 Гарячий', warm:'🟡 Теплий', cold:'🔵 Холодний'},
};
const who = o.company || o.client_name || src.name || 'Без імені';
const title = `${L.partner[partner]}: ${who} — ${L.obj[objType]}${area ? ' ' + area + ' м²' : ''}`;

const vals = {
  name: title,
  type: 'opportunity',
  team_id: TEAM,
  stage_id: 1,
  priority: {hot:'3', warm:'2', cold:'1'}[temp],
  tag_ids: [[6, 0, tags]],
  contact_name: o.client_name || src.name || false,
  partner_name: o.company || false,
  phone: src.phone || false,
  email_from: src.email || false,
  description: `<p><b>Оригінал заявки (${src.channel}):</b></p><p>${String(src.text||'').replace(/</g,'&lt;')}</p><p><b>Уточнити:</b> ${(o.missing_info||[]).join('; ') || '—'}</p>`,
  lead_properties: {
    partner_type: partner === 'unknown' ? false : partner,
    object_type: objType === 'unknown' ? false : objType,
    area_m2: area || 0,
    renovation_stage: stage === 'unknown' ? false : stage,
    systems,
    budget_usd: budget || 0,
    timeline: o.timeline || false,
    partner_source: src.partner_source || o.company || false,
    ai_score: score,
    ai_summary: `${o.summary || ''}\nНаступний крок: ${o.next_step || '—'}`,
  },
};
return [{ json: { is_target: o.is_target !== false, vals, score, temp, title, card: {
  who, partner: L.partner[partner], obj: L.obj[objType], area, stage: L.stage[stage], systems, budget,
  timeline: o.timeline, summary: o.summary, next_step: o.next_step, missing: o.missing_info || [],
  channel: src.channel, phone: src.phone, temp: L.temp[temp] } } }];

// Odoo JSON-2 create повертає масив id
const raw = $input.first().json;
const id = Array.isArray(raw) ? raw[0] : (raw.data?.[0] ?? raw.data ?? raw[0] ?? raw.id);
const c = $('Валідація + скоринг').first().json.card;
const s = $('Валідація + скоринг').first().json.score;
const esc = t => String(t ?? '—').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const sys = {lighting:'світло', climate:'клімат', security:'безпека', multiroom:'мультирум', curtains:'штори'};
const text = [
  `<b>${c.temp} лід · AI-скор ${s}/100</b>`,
  ``,
  `<b>${esc(c.who)}</b> — ${esc(c.partner)}`,
  `🏠 ${esc(c.obj)}${c.area ? ', ' + c.area + ' м²' : ''} · етап: <b>${esc(c.stage)}</b>`,
  `⚙️ ${c.systems.length ? c.systems.map(x => sys[x]).join(', ') : '—'}`,
  `💰 ${c.budget ? '$' + c.budget.toLocaleString('uk-UA') : 'бюджет не вказано'} · ⏱ ${esc(c.timeline)}`,
  `📞 ${esc(c.phone)} · канал: ${esc(c.channel)}`,
  ``,
  `📝 ${esc(c.summary)}`,
  `👉 <b>Наступний крок:</b> ${esc(c.next_step)}`,
  c.missing.length ? `❓ Уточнити: ${esc(c.missing.join('; '))}` : '',
].filter(x => x !== '').join('\n');
return [{ json: { id, text, url: `https://your-company.odoo.com/odoo/crm/${id}` } }];
